function modelGroups(t,active){return `<div class="model-groups"><div class="row between"><h3>Groupes d’exercices</h3>${btn('Grouper des exercices',active?'group-active-new':'group-model-new','small')}</div>${(t.groups||[]).map(g=>`<div class="model-group"><strong>${esc(g.name)}</strong><p class="subtitle">${g.members.map(key=>esc(groupExerciseName(t,key))+' · '+plannedPassages(exerciseByKey(t,key))).join(' → ')}</p><div class="row">${btn('Modifier',active?'group-active-edit:'+encodeURIComponent(g.id):'group-model-edit:'+encodeURIComponent(g.id),'small')}${btn('Dissocier','group-dissolve:'+(active?'active':'model')+':'+encodeURIComponent(g.id),'small')}</div></div>`).join('')}</div>`}
