function groupError(message){if($('#group-error'))$('#group-error').textContent=message;else toast(message)}
function captureGroupDraft(){if(!groupDraft||!$('#group-dialog'))return;groupDraft.name=$('#group-name').value;groupDraft.mode=$('#group-mode').value;groupDraft.common=$('#group-common')?.value||groupDraft.common;groupDraft.restBetween=num($('#group-between').value);groupDraft.restAfter=num($('#group-after').value);groupDraft.newName=$('#group-new-name')?.value||'';groupDraft.chooserOpen=$('.group-choose')?.open||false}
