function exerciseOverview(e,i){const count=e.sets.filter(s=>s.type!=='warmup').length,total=plannedSets(e);return `<article class="card exercise-summary" id="exercise-${i}"><button class="exercise-open" data-action="select:${i}" aria-expanded="false" aria-controls="exercise-entry"><span class="exercise-number">${String(workoutBlocks(state.active).findIndex(b=>b.members.includes(e.instanceId))+1).padStart(2,'0')}</span><span class="grow"><strong>${exercisePrimaryIcon(e)}<span class="live-row-name">${esc(exerciseDisplayName(e))}</span></strong><span class="subtitle">${realizedPlan(e)}</span></span><span class="exercise-state">${(isActivity(e)?!!e.activityEntries?.length:total&&count>=total)?'✓':'○'}</span><span class="live-row-chevron" aria-hidden="true">›</span></button></article>`}
function entryNumbers(e,weight,reps,prefix=''){return `<div class="entry"><div class="number-box"><label for="${prefix}weight">CHARGE · kg</label><input id="${prefix}weight" inputmode="decimal" value="${weight===''?'':fmt(weight)}" placeholder="—" aria-label="Charge en kg"><div class="row">${btn('−',prefix+'w:-1')}${btn('+',prefix+'w:1')}</div></div><div class="number-box"><label for="${prefix}reps">RÉPÉTITIONS</label><input id="${prefix}reps" inputmode="numeric" value="${reps}" aria-label="Répétitions"><div class="row">${btn('−',prefix+'r:-1')}${btn('+',prefix+'r:1')}</div></div></div><div class="row chips">${[6,7,8,9,10,12,15].map(r=>btn(r,prefix+'rep:'+r,reps===r?'selected':'')).join('')}</div>`}
function sessionTally(s){const cardio=s.exercises.filter(e=>e.tracking==='cardio'),done=cardio.filter(e=>e.activityEntries?.some(x=>x.counter==='duration')).length;const count=s.exercises.reduce((n,e)=>n+recordedSets(e).length,0),planned=s.exercises.reduce((n,e)=>n+plannedSets(e),0);return !planned&&cardio.length?`${done}/${cardio.length} exercices cardio`:`${count}/${planned} séries${cardio.length?' · '+done+'/'+cardio.length+' cardio':''}`;}
function lateralityControl(e,index=null){if(e.tracking==='cardio')return '';return `<label class="laterality-control">Côtés<select ${index===null?'id="entry-laterality"':`data-ex="${index}" data-field="laterality"`}>${options([['','Non précisé'],['bilateral','Bilatéral'],['unilateral','Unilatéral · une série par côté']],e.laterality||'')}</select></label>`}
function activityPanel(e,scope='active'){const draft=e.activityDraft||{},counter=draft.counter||e.counter||'duration',seconds=usesSeconds(e,counter),value=draft.uiValue??(draft.value===undefined?(seconds?e.activityDurationSeconds||30:''):activityDisplayValue(e,{counter,value:draft.value}));return `<section class="activity-counter">${seconds?`<input type="hidden" data-activity-counter="${scope}" value="duration"><label>Durée · secondes<input data-activity-value="${scope}" type="number" min="1" max="86400" step="1" inputmode="numeric" value="${esc(value)}" aria-label="Durée en secondes"></label>`:`<label>Compteur<select data-activity-counter="${scope}">${options(Object.entries(counters).filter(([key])=>e.tracking!=='mobility'||key==='duration').map(([key,c])=>[key,c.label+' · '+c.unit]),counter)}</select></label><label>${counters[counter].label} · ${counters[counter].unit}<input data-activity-value="${scope}" inputmode="decimal" type="text" value="${esc(value)}" placeholder="0" aria-label="${counters[counter].label} en ${counters[counter].unit}"></label>`}${btn(draft.id?'Enregistrer la correction':'Enregistrer','activity-save:'+scope,'primary wide')}${draft.id?btn('Annuler','activity-cancel:'+scope,'small'):''}<div class="activity-entries">${(e.activityEntries||[]).map((x,i)=>`<div class="row between"><strong>${fmt(activityDisplayValue(e,x))} ${activityDisplayUnit(e,x.counter)}</strong><div>${btn('Modifier',`activity-edit:${scope}:${i}`,'small')}${btn('×',`activity-delete:${scope}:${i}`,'small danger')}</div></div>`).join('')}</div>${e.tracking==='mobility'&&activityKind(e)==='Mobilité'?'<p class="subtitle">Contractions progressives sans douleur. Note la durée réalisée.</p>':''}</section>`}
function cardioExercise(){return state.active?.exercises.find(e=>e.instanceId===state.active.cardioOverlayKey)}
