let cardioRetryAfter=0;
function updateCardioClock(){if(Date.now()<cardioRetryAfter)return;if(creationSaving||validationBusy||correctionSaving)return;for(const e of state.active?.exercises||[]){const t=e.cardioTimer;if(!t||t.status==='finished')continue;const ms=remainingCardio(t);for(const el of document.querySelectorAll('[data-cardio-clock]'))if(el.dataset.cardioClock===e.instanceId)el.textContent=cardioTime(ms);if(cardioExercise()===e){if($('#cardio-countdown'))$('#cardio-countdown').textContent=cardioTime(ms);const meter=$('.cardio-meter i');if(meter)meter.style.width=(100*ms/t.durationMs)+'%'}if(t.status==='running'&&ms<=0){cardioAction('cardio-complete:'+e.instanceId).catch(error=>{cardioRetryAfter=Date.now()+5000;toast('Durée à enregistrer. Nouvelle tentative dans quelques secondes.')});break}}}
