function activityWork(e){return `<article class="card exercise-active" id="exercise-${selected}"><div id="exercise-entry"><h2><button class="exercise-title-link" data-action="exercise-open:active:${selected}" aria-label="Voir la fiche de ${esc(exerciseDisplayName(e))}">${exercisePrimaryIcon(e)}${esc(exerciseDisplayName(e))}</button></h2>${isTimedExercise(e)?cardioEntry(e):activityPanel(e)}${lateralityControl(e)}<div class="row between"><span class="subtitle">${counterCount(e)}</span>${btn('Suivant →','next','small')}</div></div></article>`}
async function activityAction(a){if(!a.startsWith('activity-'))return false;const [key,scope,index]=a.split(':'),e=scope==='active'?ex():state.sessions.find(s=>s.id===detail)?.exercises[Number(scope)];if(!isActivity(e))throw Error('Compteur indisponible.');const before=clone(e),activeBefore=scope==='active'?clone(state.active):null,previousSelected=selected;if(key==='activity-save'){const counter=document.querySelector(`[data-activity-counter="${scope}"]`).value,value=document.querySelector(`[data-activity-value="${scope}"]`).value,entry=activityEntry(counter,activityInputValue(e,counter,value),e.activityDraft?.id),i=(e.activityEntries||[]).findIndex(x=>x.id===entry.id);e.activityEntries??=[];if(i>=0)e.activityEntries[i]={...e.activityEntries[i],...entry};else e.activityEntries.push(entry);e.counter=counter;if(e.cardioTimer?.id===entry.id){if(counter==='duration')e.cardioTimer.elapsedMs=entry.value*60000;else delete e.cardioTimer}delete e.activityDraft;if(scope==='active'&&i<0&&(!e.cardioTimer||e.cardioTimer.status==='finished')){const g=currentGroup(),step=currentStage(e);if(g&&step){entry.groupId=g.id;entry.groupStepId=step.id;advanceActivityPassage(e,g,step)}}}else if(key==='activity-edit'){e.activityDraft={...e.activityEntries[Number(index)]}}else if(key==='activity-cancel'){delete e.activityDraft}else if(key==='activity-delete'){if(!confirm('Supprimer ce relevé ?'))return true;const removed=e.activityEntries.splice(Number(index),1)[0];if(e.cardioTimer?.id===removed?.id)delete e.cardioTimer}creationSaving=true;try{await save();render()}catch(error){Object.keys(e).forEach(k=>delete e[k]);Object.assign(e,before);if(activeBefore){state.active=activeBefore;selected=previousSelected;timerEnd=activeBefore.restUntil||0;prepare()}render();throw error}finally{creationSaving=false}return true}
