function recapProgressSection(s,items){const improvements=items.filter(item=>!item.records.length).map(item=>({item,progress:item.current.map(set=>setProgression(s,item.e,set,state.sessions)).find(Boolean)})).filter(x=>x.progress);return improvements.length?`<section class="card recap-progress"><div class="eyebrow">DEPUIS LA DERNIÈRE FOIS</div><h2>Les progrès du jour.</h2>${improvements.map(({item,progress:p})=>`<div class="recap-progress-row"><strong>${esc(item.e.name)}</strong><span>${progressionLabel(p)}</span><small>${fmt(p.old.w)} ${p.unit} × ${p.old.r} → ${fmt(p.set.w)} ${p.unit} × ${p.set.r}</small></div>`).join('')}</section>`:''}
function recapRecordSection(items){const featured=items.filter(item=>item.records.length);return featured.length?`<section class="card achievement-summary"><div class="eyebrow">TES NOUVEAUX REPÈRES</div><h2>Une étape de plus.</h2>${featured.map(item=>`<div class="recap-record"><strong>${esc(item.e.name)}</strong>${[...new Map(item.records.map(r=>[r.kind,r])).values()].map(r=>`<p>${recordBadge(r)} <span>${recordValue(r)}</span><small class="recap-record-before">Avant : ${recordPrevious(r)} · ${recordChange(r)}</small></p>`).join('')}</div>`).join('')}<p class="subtitle">Records calculés sur ton historique enregistré, à équipement et convention identiques. Les égalités ne créent pas de nouveau record.</p></section>`:''}
function sessionSheet(){const s=state.sessions.find(s=>s.id===detail);if(!s)return home();const duration=s.endedAt&&Number.isFinite(Date.parse(s.date))?Math.max(0,Math.round((Date.parse(s.endedAt)-Date.parse(s.date))/60000)):null,items=sessionRecap(s,state.sessions),tonnageSummary=normalizedTonnage(s.exercises),changes=sessionComparison(s,state.sessions),total=items.reduce((n,x)=>n+x.current.length,0),planned=s.exercises.reduce((n,e)=>n+plannedSets(e),0);return `<section class="finish-summary"><div class="eyebrow">SÉANCE ENREGISTRÉE</div><h1>${esc(s.name)}</h1><p class="subtitle">${date(s.date)}</p><p class="muted">L’effort est fait. Voici ce qui a changé.</p><p class="subtitle">${s.exercises.filter(e=>e.sets?.length||e.activityEntries?.length).length} / ${s.exercises.length} exercices réalisés</p><div class="activity-stats"><div><strong>${total}</strong><span>séries de travail</span></div><div><strong>${fmt(tonnageSummary.complete?tonnageSummary.knownTonnage:tonnageSummary.rawTonnage)} kg</strong><span>${tonnageSummary.complete?'tonnage normalisé':'tonnage renseigné'}</span></div>${duration!==null?`<div><strong>${duration} min</strong><span>durée écoulée</span></div>`:''}</div><p class="recap-plan">${total} série${total>1?'s':''} réalisée${total>1?'s':''} · ${planned} prévue${planned>1?'s':''} <span class="subtitle">${items.reduce((n,x)=>n+Math.max(0,x.current.length-plannedSets(x.e)),0)} supplémentaires · ${items.reduce((n,x)=>n+Math.max(0,plannedSets(x.e)-x.current.length),0)} non réalisées</span></p><p class="subtitle">Prévu : objectif conservé dans cette séance. Les échauffements ne comptent pas comme séries de travail. La durée inclut les pauses.</p>${recapRecordSection(items)}${recapProgressSection(s,items)}${comparisonControls(s)}${radarHtml(s,state.sessions.find(x=>x.id===comparisonId)||null)}<h2>Exercice par exercice</h2><p class="subtitle">${items.filter(item=>item.priorSession).length} / ${items.length} exercices avec une séance précédente comparable. Les écarts au plan restent distincts.</p>${items.map((item,i)=>{if(isActivity(item.e))return `<article class="card recap-exercise"><h3>${item.e.tracking==='cardio'?exercisePrimaryIcon(item.e):''}${esc(exerciseDisplayName(item.e))}</h3>${(item.e.activityEntries||[]).map(x=>`<p>${fmt(activityDisplayValue(item.e,x))} ${activityDisplayUnit(item.e,x.counter)}</p>`).join('')||'<p class="muted">Non réalisé</p>'}</article>`;const {e,current,priorSession,previous,volume,deltaSets,deltaVolume,best,repGain}=item;return `<article class="card recap-exercise"><h3>${exercisePrimaryIcon(e)}${esc(exerciseDisplayName(e))}</h3>${btn('Fiche exercice','exercise-open:detail:'+i,'small')}<p class="recap-plan"><strong>${current.length} série${current.length>1?'s':''}</strong> · ${plannedSets(e)} prévues</p>${best?`<p>Meilleure série : <strong>${fmt(best.w)} kg × ${best.r}</strong></p><p class="subtitle">${fmt(volume)} kg cumulés · ${current.reduce((n,x)=>n+x.r,0)} répétitions principales</p>`:'<p class="muted">Non réalisé</p>'}${priorSession?`<p class="subtitle">Comparaison avec le ${date(priorSession.date)} · même équipement et convention</p><div class="recap-deltas"><span>${deltaSets>0?'+':''}${deltaSets} série${Math.abs(deltaSets)>1?'s':''} · ${previous.length} précédemment</span><span>${deltaVolume>0?'+':''}${fmt(deltaVolume)} kg de tonnage</span>${repGain!==null&&repGain!==0?`<span class="comparison-fact">${repGain>0?'+':''}${repGain} répétition${Math.abs(repGain)>1?'s':''} à ${fmt(best.w)} kg par rapport à la fois précédente</span>`:''}</div>`:'<p class="subtitle">Pas de comparaison fiable disponible pour cet exercice.</p>'}<details><summary>Détail des séries et comparaisons</summary>${e.sets.map(x=>`<p class="subtitle">${fmt(x.w)} kg × ${x.r}${x.type==='warmup'?' · échauffement':''}${x.drops?.length?' ↘ '+x.drops.map(d=>fmt(d.w)+' kg × '+d.r).join(' → '):''}</p>`).join('')}${(changes[i]?.changes||[]).map(c=>`<p class="comparison-fact">Série ${c.index+1} : ${c.kind==='reps'?`+${c.gain} répétition${c.gain>1?'s':''} à ${fmt(c.set.w)} kg`:c.kind==='weight'?`+${fmt(c.gain)} kg à ${c.set.r} répétitions`:`${fmt(c.old.w)} kg × ${c.old.r} → ${fmt(c.set.w)} kg × ${c.set.r} · conditions différentes`}</p>`).join('')}</details></article>`}).join('')}${omittedExercises(s,state.sessions).length?`<details class="recap-omitted"><summary>Absents par rapport à la séance précédente</summary><p class="subtitle">Le contenu de cette séance a changé. Aucune série manquante n’est ajoutée au programme.</p>${omittedExercises(s,state.sessions).map(e=>`<p>${esc(exerciseDisplayName(e))} · ${e.sets} série${e.sets>1?'s':''} le ${date(e.date)}</p>`).join('')}</details>`:''}${sessionTonnageDetails(s)}${sessionMuscles(s)}<div class="row">${btn('Modifier ou supprimer','summary-detail','grow')}${btn('Retour à l’accueil','nav:home','grow')}</div></section>`}

function rememberBodyDraft(){if(!$('#body-form'))return;bodyDraft={key:(bodyEditing||'new')+':'+bodyMode,date:$('#body-date').value,values:Object.fromEntries([...document.querySelectorAll('[data-body-field]')].map(el=>[el.dataset.bodyField,el.value]))}}
function restoreBodyDraft(){if(!bodyDraft||!$('#body-form')||bodyDraft.key!==(bodyEditing||'new')+':'+bodyMode)return;$('#body-date').value=bodyDraft.date;for(const el of document.querySelectorAll('[data-body-field]'))el.value=bodyDraft.values[el.dataset.bodyField]??''}
function weightAveragePanel(records){const duplicateDays=records.filter(m=>Number.isFinite(m.values.weight)).length-dailyWeights(records).length;const all=rollingWeight(records),points=all.filter(p=>bodyPeriod==='all'||p.date>=dayOffset(dayKey(),-Number(bodyPeriod)+1)),latest=points.at(-1);return `<label class="row"><input id="weight-average" type="checkbox" ${showWeightAverage?'checked':''}>Afficher la moyenne mobile sur 14 jours</label>${showWeightAverage&&latest?`<section class="weight-average"><h3>Moyenne mobile · 14 jours</h3>${duplicateDays?`<p class="subtitle">${duplicateDays} doublon(s) de date : seule la première pesée de chaque date est retenue pour le calcul. Les relevés restent modifiables.</p>`:''}<p><strong>${fmt(Number(latest.value.toFixed(2)))} kg</strong> · ${latest.days} jour${latest.days>1?'s':''} mesuré${latest.days>1?'s':''} sur 14 au ${dayLabel(latest.date)}</p>${latest.days<2?'<p class="subtitle">Une seule pesée dans cette fenêtre : aucune tendance ne peut être déduite.</p>':''}${points.length>1?trendChart(points,'kg','body-edit','weight-average-chart'):''}<details><summary>Mesures utilisées</summary>${points.map(p=>`<p class="subtitle">${dayLabel(p.date)} : ${fmt(Number(p.value.toFixed(2)))} kg · ${p.days} jour${p.days>1?'s':''} mesuré${p.days>1?'s':''}</p>`).join('')}<p class="subtitle">Moyenne des pesées disponibles du jour et des 13 jours précédents. Les jours sans pesée ne comptent pas. Une fiche par date ; les doublons d’import sont ignorés en conservant la fiche locale.</p></details></section>`:''}`}
function unclassifiedLinks(s,active){return s.exercises.map((e,i)=>({e,i})).filter(({e})=>workSets(e).length&&!e.muscles?.primary.length).map(({e,i})=>btn('Renseigner : '+esc(exerciseDisplayName(e)),active?'muscle-session:'+i:'muscle-history:'+i,'small')).join('')}
let historyRange='all',historyDayOnly=false,historyCalendarVisible=true;
function history(){
 const month=calendarMonth,year=month.slice(0,4),valid=state.sessions.filter(s=>Number.isFinite(Date.parse(s.date))),matching=valid.filter(s=>(!filter||s.templateId===filter)&&(!historyExercise||s.exercises.some(e=>e.id===historyExercise&&e.sets?.length))&&(historyPeriod==='all'||Date.now()-new Date(s.date)<Number(historyPeriod)*864e5)),periodSessions=matching.filter(s=>historyRange==='all'?true:['7','30'].includes(historyRange)?dayKey(s.date)>=dayOffset(dayKey(),-Number(historyRange)+1):historyRange==='year'?dayKey(s.date).startsWith(year):dayKey(s.date).startsWith(month)),selectedDay=historySelectedDay(month,calendarDay,matching),sessions=periodSessions.filter(s=>!historyDayOnly||dayKey(s.date)===selectedDay).sort((a,b)=>Date.parse(b.date)-Date.parse(a.date));
 return `<section class="history-intro"><div class="eyebrow">TON JOURNAL D’ENTRAÎNEMENT</div><h1>Historique.</h1><p class="history-description">Retrouve tes séances et analyse ton activité.</p><details class="history-search social-disclosure" data-panel-key="history-search"><summary aria-label="Rechercher et filtrer l’historique">${icon('search')}</summary><div class="history-search-fields"><label>Séance<select id="filter">${options([['','Toutes les séances'],...state.templates.map(t=>[t.id,t.name])],filter)}</select></label><label>Exercice<select id="history-exercise">${options([['','Tous les exercices'],...allExercises().map(e=>[e.id,exerciseDisplayName(e)])],historyExercise)}</select></label><label>Intervalle avancé<select id="history-period">${periodOptions(historyPeriod)}</select></label><label>Journée<input id="history-selected-day" type="date" value="${selectedDay}"></label><label class="row history-check"><input id="history-day-only" type="checkbox" ${historyDayOnly?'checked':''}>Uniquement cette journée</label><label class="row history-check"><input id="history-calendar-visible" type="checkbox" ${historyCalendarVisible?'checked':''}>Afficher le calendrier</label></div></details></section><div class="history-period-stats" role="group" aria-label="Période de l’historique">${[['all','Tout'],['7','7 jours'],['30','30 jours'],['month','Ce mois'],['year','Cette année']].map(([key,label])=>`<button data-action="history-scope:${key}" aria-pressed="${historyRange===key}">${label}</button>`).join('')}</div>${activityStrip(savedActivity(periodSessions,state.active?.id),{label:'Activité de la période sélectionnée',className:'history-activity'}).replace('Séries de travail','Séries').replace('Temps enregistré','Temps total')}${historyCalendarVisible?`<div class="history-calendar-summary"><section class="history-calendar" aria-label="Calendrier d’entraînement">${activityCalendar(selectedDay)}</section>${historyDayHtml(selectedDay,matching)}</div>`:''}<div class="row between history-recent-heading"><h2>Dernières séances</h2><button type="button" class="history-filter-toggle" data-action="history-search-toggle">${icon('settings')}<span>Filtrer</span></button></div>${historyDayOnly?`<p class="history-day-filter"><button type="button" class="small" data-action="history-day-filter-clear">${dayLabel(selectedDay)} <span aria-hidden="true">×</span><span class="sr-only">Retirer le filtre de journée</span></button></p>`:''}${sessions.map(historySessionRow).join('')||'<div class="empty history-list-empty">Aucune séance pour cette période.</div>'}<details class="calendar-disclosure"><summary>Régularité et statistiques</summary>${regularitySummary()}</details><p class="history-tonnage-link">${btn('Voir le tonnage dans Progression','overview-tonnage','small')}</p>`;
}
function regularitySummary(){const stats=attendance(state.sessions);return `<div class="activity-stats">${[[stats.total,'depuis le début'],[fmt(stats.weekly),'séances / semaine']].map(([v,label])=>`<div><strong>${v}</strong><span>${label}</span></div>`).join('')}</div><p class="subtitle">Moyenne des 28 derniers jours, divisée par quatre. Séances avec au moins une série.</p>`}

function sessionEditorDetails(){const s=state.sessions.find(s=>s.id===detail);if(!s)return history();return `<h3>Modifier la séance</h3><label>Date<input id="session-date" type="date" value="${dayKey(s.date)}"></label><p class="session-tonnage"><strong>${fmt(tonnage(s))} kg cumulés</strong></p><p class="subtitle">${tonnageNote}</p><div class="row">${btn('Préparer une nouvelle séance','duplicate-session')}${btn('Supprimer','delete-session','danger')}</div>${btn('Voir le bilan','show-recap','small')}${historyGroups(s)}${s.exercises.map((e,j)=>`<div class="card"><h3>${exercisePrimaryIcon(e)}${esc(exerciseDisplayName(e))}</h3>${muscleTags(e)}${btn('Modifier les muscles','muscle-history:'+j,'small')}${groupForExercise(s,e.instanceId)?`<p class="superset-history">${esc(groupForExercise(s,e.instanceId).name)}</p>`:''}<p class="subtitle">${esc(e.note)} · ${esc(e.convention)}</p>${isActivity(e)?activityPanel(e,String(j)):e.sets.map((x,i)=>setRow(x,i,String(j))).join('')||'<p class="muted">Aucune série validée</p>'}</div>`).join('')}`}
function allExercises(){return [...new Map([...state.sessions,...state.templates,...(state.active?[state.active]:[])].flatMap(t=>t.exercises.flatMap(e=>[e,...(e.alternative?[e.alternative]:[])])).map(e=>[e.id,e])).values()]}
const periodOptions=v=>options([['30','1 mois'],['90','3 mois'],['180','6 mois'],['all','Tout l’historique']],v);
function progress(){const e=performanceExercise(exerciseId)||allExercises()[0];exerciseId=e?.id;if(e&&loadIdentity(e).certainty!=='known')return `<label>Exercice / équipement<select id="exercise">${options(allExercises().map(x=>[x.id,exerciseLabel(x.name)]),exerciseId)}</select></label><label>Période<select id="period">${periodOptions(period)}</select></label><details class="progress-help"><summary>Comprendre les données</summary><p>Convention à confirmer : les performances anciennes restent consultables séparément.</p></details>${sheetHtml({exercise:e,sessions:state.sessions.filter(s=>period==='all'||dayKey(s.date)>=dayOffset(dayKey(),-Number(period)+1))})}${btn('Convention et fiche complète','exercise-open:'+encodeURIComponent(e.id),'small')}`;const points=state.sessions.filter(s=>period==='all'||dayKey(s.date)>=dayOffset(dayKey(),-Number(period)+1)).sort((a,b)=>a.date.localeCompare(b.date)).flatMap(s=>{const sets=s.exercises.filter(x=>x.id===exerciseId).flatMap(x=>workSets(x).filter(set=>loadIdentity(e).certainty==='known'?sameLoadIdentity(e,x,null,set):x.convention===e.convention&&!set.loadIdentity));return sets.length?[{s,sets:sets.flatMap(x=>[x,...(x.drops||[])])}]:[]});const charges=[...new Set(points.flatMap(p=>p.sets.map(x=>x.w)))].sort((a,b)=>a-b);if(!charges.includes(num(charge)))charge=String(charges.at(-1)??'');const repPoints=points.map(p=>({...p,sets:p.sets.filter(x=>x.w===num(charge))})).filter(p=>p.sets.length),last=points.at(-1);return `<label>Exercice / équipement<select id="exercise">${options(allExercises().map(e=>[e.id,exerciseDisplayName(e)]),exerciseId)}</select></label><label>Période<select id="period">${periodOptions(period)}</select></label><section class="card performance-recap"><h2>Dernière performance</h2>${last?`<p>${date(last.s.date)} · ${last.sets.map(x=>fmt(x.w)+' kg × '+x.r).join(' · ')}</p><p>Charge maximale sur la période : <strong>${fmt(Math.max(...charges))} kg</strong></p>`:'<p class="muted">Aucune série de travail enregistrée sur cette période.</p>'}<details><summary>Records de répétitions par charge</summary>${charges.map(w=>`<p>${fmt(w)} kg · <strong>${Math.max(...points.flatMap(p=>p.sets).filter(x=>x.w===w).map(x=>x.r))} rép.</strong></p>`).join('')||'<p class="muted">Aucun record enregistré.</p>'}</details></section><div class="card"><h3>Évolution des charges</h3><p class="subtitle">kg · Séries de travail validées uniquement</p>${chart(points,p=>Math.max(...p.sets.map(x=>x.w)),'kg')}</div><div class="card"><h3>Répétitions à charge égale</h3><label>Charge<select id="charge">${options(charges.map(w=>[w,fmt(w)+' kg']),charge)}</select></label>${chart(repPoints,p=>Math.max(...p.sets.map(x=>x.r)),'rép.')}<p class="subtitle">Une répétition supplémentaire reste visible, même sans changer de charge.</p></div><details><summary>Volume de cet exercice · complément</summary><p class="subtitle">Somme charge × répétitions, dégressives incluses. Aucune conversion des conventions de charge.</p>${points.map(p=>`<p>${date(p.s.date)} · ${fmt(p.sets.reduce((n,x)=>n+x.w*x.r,0))} kg·rép.</p>`).join('')}</details>`}
function chart(points,value,unit){if(!points.length)return '<div class="empty">Tes premières séries dessineront la courbe.<br>Les références initiales ne sont pas des séances.</div>';const max=Math.max(1,...points.map(value));const first=Date.parse(points[0].s.date),last=Date.parse(points.at(-1).s.date);const coords=points.map(p=>[35+(last===first?.5:(Date.parse(p.s.date)-first)/(last-first))*330,160-value(p)/max*120]);return `<svg class="chart" viewBox="0 0 410 215" role="img" aria-label="Progression en ${unit}"><path d="M35 25V165H380" stroke="#3c4738" fill="none"/>${points.length>1?`<polyline points="${coords.map(c=>c.join(',')).join(' ')}" fill="none" stroke="#c5f279" stroke-width="2"/>`:''}${points.map((p,i)=>`<g><text x="${coords[i][0]}" y="${coords[i][1]-12}" text-anchor="middle">${fmt(value(p))} ${unit}</text><circle tabindex="0" role="button" aria-label="${date(p.s.date)} : ${fmt(value(p))} ${unit}" data-action="detail:${p.s.id}" cx="${coords[i][0]}" cy="${coords[i][1]}" r="8"><title>${date(p.s.date)} · ${fmt(value(p))} ${unit}</title></circle>${i===0||i===points.length-1?`<text x="${coords[i][0]}" y="193" text-anchor="middle">${date(p.s.date)}</text>`:''}</g>`).join('')}</svg>`}
let creationDraft=state.templateDraft||null,creationSaving=false,exercisePicker=null,templateExplorer=false;
function openCreation(source=null){creationDraft=source?{...cleanPlan(source),id:uid(),workoutType:workoutType(source)||'',name:source.name+' · copie'}:creationDraft||{id:uid(),name:'Nouvelle séance',exercises:[],groups:[]};state.templateDraft=creationDraft;modelId='new';view='models';render();window.scrollTo(0,0);save().catch(error=>toast(error.message))}
function simplePrescription(e,i){if(isActivity(e))return `<div class="simple-prescription"><label>Durée · secondes<input data-ex="${i}" data-field="${isTimedExercise(e)?'cardioSeconds':'activityDurationSeconds'}" aria-label="Durée prévue ${esc(exerciseDisplayName(e))} en secondes" inputmode="numeric" value="${isTimedExercise(e)?plannedCardioSeconds(e):e.activityDurationSeconds||30}"></label>${isTimedExercise(e)?`<label>Passages<input data-ex="${i}" data-field="activityRounds" inputmode="numeric" aria-label="Passages ${esc(exerciseDisplayName(e))}" value="${plannedPassages(e)}"></label>`:''}</div>`;const rx=e.prescription||prescription(e,state.programmingPreferences,state.sessions);return `<div class="simple-prescription"><label>Répétitions · min<input aria-label="Répétitions minimum ${esc(exerciseDisplayName(e))}" data-ex="${i}" data-field="repMin" inputmode="numeric" value="${rx.repMin}"></label><label>max<input aria-label="Répétitions maximum ${esc(exerciseDisplayName(e))}" data-ex="${i}" data-field="repMax" inputmode="numeric" value="${rx.repMax}"></label><label>Repos · secondes<input aria-label="Repos ${esc(exerciseDisplayName(e))}" data-ex="${i}" data-field="rest" inputmode="numeric" value="${e.rest}"></label></div>`}
function editorPreview(t){const v=plannedVolume(t),prefs={...state.programmingPreferences,...t.timing},time=estimateDuration(t,prefs),worked=muscles.filter(([id])=>v.totals[id].primary||v.totals[id].secondary),top=[...worked].sort((a,b)=>v.totals[b[0]].primary-v.totals[a[0]].primary).slice(0,3);return `<details class="editor-live-preview"><summary><strong>${v.sets} séries · ${time.range[0]}–${time.range[1]} min</strong><span>${top.map(([id,label])=>esc(label)+' '+v.totals[id].primary).join(' · ')||'Choisis tes exercices'}</span><small>Détail par muscle</small></summary><div class="editor-muscle-grid"><strong>Muscle</strong><strong>Directes</strong><strong>Secondaires</strong>${worked.map(([id,label])=>`<span>${esc(label)}</span><span aria-label="${esc(label)}, ${v.totals[id].primary} séries directes prévues">${v.totals[id].primary}</span><span aria-label="${esc(label)}, ${v.totals[id].secondary} séries secondaires prévues">${v.totals[id].secondary}</span>`).join('')}</div>${v.unclassified?`<p>${v.unclassified} séries à classer.</p>`:''}<p class="subtitle">Estimation : échauffement, préparations, repos configurés, installation, transitions et marge inclus. Les préparations ne comptent pas dans les séries de travail. L’ordre réel des tours est pris en compte.</p></details>`}
function updateEditorPreview(){const host=$('#editor-preview'),t=target();if(!host||!t)return;if(host.closest('.session-editor')&&host.querySelector('details')){const holder=document.createElement('div');holder.innerHTML=editorPreview(t);const current=host.querySelector('details'),next=holder.querySelector('details');for(const tag of ['strong','span','small'])current.querySelector('summary '+tag).textContent=next.querySelector('summary '+tag).textContent;for(const child of [...current.children])if(child.tagName!=='SUMMARY')child.remove();for(const child of [...next.children])if(child.tagName!=='SUMMARY')current.append(child);return}const open=host.querySelector('details')?.open;host.innerHTML=editorPreview(t);host.querySelector('details').open=!!open}
function openExercisePicker(replace=null){const modern=!['active','planning'].includes(modelId);exercisePicker={replace,modern,selected:new Set(),query:'',muscle:'',equipment:'',choices:modern?editorLibrary(state):catalogue(state,{...state.programmingPreferences,enabledAlternatives:genericAlternatives.map(a=>a.key)})};render();const dialog=$('#exercise-picker');dialog.showModal();$('#exercise-picker-title').focus()}
function exercisePickerDialog(){if(exercisePicker.modern)return multiPicker(exercisePicker,state);return `<dialog id="exercise-picker" aria-labelledby="exercise-picker-title"><div class="row between"><h2 id="exercise-picker-title" tabindex="-1" autofocus>Choisir un exercice</h2>${btn('Fermer','picker-close','small')}</div><label>Rechercher<input id="exercise-search" type="search" placeholder="Exercice ou muscle" autocomplete="off"></label><div class="exercise-results">${exercisePicker.choices.map((e,i)=>{const p=exerciseProfile(e,state.programmingPreferences);return `<button class="exercise-choice" data-search="${esc(exerciseSearchText(e.name))}" data-action="picker-add:${i}"><strong>${exercisePrimaryIcon(e)}${esc(exerciseDisplayName(e))}</strong><small>${p.muscles.primary.map(muscleName).join(' · ')||(isActivity(e)?e.tracking==='cardio'?'Cardio':'Mobilité':'Muscles à préciser')} · ${isActivity(e)?'Compteur au choix':esc(e.convention)}</small></button>`}).join('')}</div><p id="exercise-search-empty" hidden>Aucun exercice trouvé.</p></dialog>`}
function captureEditorNames(){const t=target();if(!t)return;for(const el of document.querySelectorAll('[data-field="name"]')){const obj=el.dataset.ex===undefined?t:t.exercises[Number(el.dataset.ex)];if(!obj)continue;if(obj!==t&&!obj.customName&&el.value===el.defaultValue)continue;const name=el.value.trim();if(!name)throw Error('Donne un nom à ton exercice.');if(obj!==t&&name!==obj.name)obj.customName=true;obj.name=name;}}
function simpleTrainingInput(el){if(exercisePicker?.modern&&el.closest('#exercise-picker')){capturePicker(el);filterPicker();return true}if(el.id==='exercise-search'){const query=el.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();let visible=0;for(const row of document.querySelectorAll('.exercise-choice')){row.hidden=!(row.dataset.search+' '+row.textContent).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(query);if(!row.hidden)visible++}$('#exercise-search-empty').hidden=!!visible;return true}if(el.dataset.field&&($('#editor-preview')||el.closest('.session-editor'))){const t=target(),obj=el.dataset.ex===undefined?t:t.exercises[Number(el.dataset.ex)],f=el.dataset.field,n=num(el.value);if(f==='name'){obj.name=el.value;if(obj!==t)obj.customName=true;}else if(f==='rest'&&el.value.trim()&&Number.isFinite(n)&&n>=0)obj.rest=n;else if(['repMin','repMax'].includes(f)&&el.value.trim()&&Number.isInteger(n)&&n>=1&&n<=10000){const rx={...(obj.prescription||prescription(obj,state.programmingPreferences,state.sessions)),manual:true};rx[f]=n;if(rx.repMax>=rx.repMin)obj.prescription=rx}updateEditorPreview()}return false}
function capturePicker(el){const fields={'exercise-search':'query','picker-muscle':'muscle','picker-equipment':'equipment','picker-custom-name':'customName','picker-custom-muscle':'customMuscle','picker-custom-equipment':'customEquipment','picker-custom-tracking':'customTracking'};if(fields[el.id])exercisePicker[fields[el.id]]=el.value}
function filterPicker(){if(!exercisePicker?.modern)return;const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),q=norm(exercisePicker.query);let count=0;for(const row of document.querySelectorAll('.exercise-choice')){row.hidden=!((exercisePicker.scope!=='recent'||row.dataset.recent==='true')&&norm(row.dataset.search+' '+row.textContent).includes(q)&&(!exercisePicker.muscle||row.dataset.muscles.split(' ').includes(exercisePicker.muscle))&&(!exercisePicker.equipment||row.dataset.equipment===exercisePicker.equipment));if(!row.hidden)count++}$('#exercise-search-empty').hidden=!!count}
function redrawPicker(){render();$('#exercise-picker').showModal();filterPicker()}
async function editorCount(index,count){const t=target(),e=t.exercises[index];if(!Number.isInteger(count)||count<0||count>100){const input=document.querySelector(`[data-ex="${index}"][data-field="count"]`);if(input)input.value=String(plannedSets(e));throw Error('Prévois entre 0 et 100 séries.')}const g=groupForExercise(t,e.instanceId),before=clone(t);if(g?.mode==='rotating'){openGroupEditor(t,g,{key:e.instanceId,count});return}if(g){const config=groupConfig(t,g);config.counts[e.instanceId]=count;const updated=configureGroup(t,config,false);for(const [field,value]of Object.entries(g))if(!(field in updated))updated[field]=clone(value)}else setPlannedSets(e,count);try{await save()}catch(error){Object.assign(t,before);render();throw error}}
async function modernEditorAction(a){const [k,v,z]=a.split(':');if(k==='editor-discard'){if(confirm('Supprimer ce brouillon ? Tes séances enregistrées restent conservées.'))await simpleTrainingAction('cancel-created');return true}if(k==='editor-type'){const t=target(),old=workoutTypes.find(([key])=>key===workoutType(t))?.[1],label=workoutTypes.find(([key])=>key===v)?.[1]||'Nouvelle séance';if(!t.name||t.name==='Nouvelle séance'||t.name===old)t.name=label;t.workoutType=v;await save();render();return true}if(k==='editor-order'){const el=document.querySelectorAll('.model-exercise')[Number(v)]?.querySelector('details');if(el){el.open=true;el.querySelector('.editor-move select')?.focus()}return true}if(k==='template-owned'){if(modelId==='new'&&creationDraft?.exercises.length&&!confirm('Remplacer le brouillon par cette séance ?'))return true;templateExplorer=false;const source=state.templates.find(t=>t.id===decodeURIComponent(v));if(source)openCreation(source);return true}if(k==='picker-scope'&&exercisePicker){exercisePicker.scope=v;for(const b of document.querySelectorAll('[data-action^="picker-scope:"]'))b.classList.toggle('selected',b.dataset.action==='picker-scope:'+v);filterPicker();return true}if(k==='explore-models'){if(exercisePicker?.selected?.size&&!confirm('Quitter cette sélection pour explorer les modèles ?'))return true;exercisePicker=null;templateExplorer=true;render();$('#template-library').showModal();$('#template-library-title').focus();return true}if(k==='templates-close'){templateExplorer=false;render();return true}if(k==='template-choose'){if(modelId==='new'&&creationDraft?.exercises.length&&!confirm('Remplacer le brouillon par ce modèle ?'))return true;templateExplorer=false;const source=optionalTemplates()[Number(v)];openCreation(source);creationDraft.name=source.name;render();await save();return true}if(k==='model-editor-close'){captureEditorNames();await save();modelId=null;view='home';render();return true}if(k==='plan-edit'&&view==='models'&&!['active','planning'].includes(modelId)&&!v.includes('.')){await editorCount(Number(v),Math.max(0,Math.min(100,plannedSets(target().exercises[Number(v)])+Number(z))));return true}if(!exercisePicker?.modern||!k.startsWith('picker-')||k==='picker-close')return false;if(k==='picker-toggle'){const index=Number(v);if(exercisePicker.replace!==null)exercisePicker.selected=new Set([index]);else if(exercisePicker.selected.has(index))exercisePicker.selected.delete(index);else exercisePicker.selected.add(index);for(const el of document.querySelectorAll('.exercise-choice[data-action^="picker-toggle:"]')){const selected=exercisePicker.selected.has(Number(el.dataset.action.split(':')[1]));el.classList.toggle('selected',selected);el.setAttribute('aria-pressed',String(selected))}const count=$('.picker-selected-count');if(count)count.textContent=exercisePicker.selected.size+' sélectionné'+(exercisePicker.selected.size>1?'s':'');const apply=$('[data-action="picker-apply"]');apply.disabled=!exercisePicker.selected.size;apply.textContent=(exercisePicker.replace===null?'Ajouter':'Remplacer')+' ('+exercisePicker.selected.size+')';return true}if(k==='picker-custom-add'){const name=exercisePicker.customName?.trim();if(!name)throw Error('Donne un nom à ton exercice.');const tracking=exercisePicker.customTracking||'strength',e={id:uid(),name,note:'',convention:'Valeur indiquée (à préciser)',step:2.5,rest:90,auto:false,refs:[],refsAreTargets:true,plannedSets:tracking==='strength'?3:0,sets:[],muscles:{primary:exercisePicker.customMuscle?[exercisePicker.customMuscle]:[],secondary:[]},equipment:exercisePicker.customEquipment||'unknown',movement:'unknown',demand:'unknown',...(tracking!=='strength'?{tracking,counter:'duration',activityEntries:[]}:{} )};exercisePicker.choices.push(e);if(exercisePicker.replace!==null)exercisePicker.selected.clear();exercisePicker.selected.add(exercisePicker.choices.length-1);exercisePicker.query='';exercisePicker.muscle='';exercisePicker.equipment='';redrawPicker();return true}if(k==='picker-apply'){if(!exercisePicker.selected.size)return true;const t=target(),before=clone(t),picker=exercisePicker;for(const index of picker.selected){const e=clone(picker.choices[index]);e.instanceId=uid();e.sets=[];if(e.activityEntries)e.activityEntries=[];delete e.activityDraft;delete e.cardioTimer;delete e.superset;if(e.alternative){e.alternative.sets=[];e.alternative.instanceId=e.instanceId}if(picker.replace===null)t.exercises.push(e);else{const old=t.exercises[picker.replace];if(groupForExercise(t,old.instanceId))throw Error('Dissocie le groupe avant de remplacer cet exercice.');if(hasRecorded(old))throw Error('Cet exercice contient des performances enregistrées.');t.exercises[picker.replace]=e}}creationSaving=true;try{await save();exercisePicker=null;render()}catch(error){Object.assign(t,before);exercisePicker=picker;redrawPicker();throw error}finally{creationSaving=false}return true}return false}
async function simpleTrainingAction(a){const [k,v]=a.split(':');if(k==='delete-model'){const index=state.templates.findIndex(t=>t.id===decodeURIComponent(v));if(index<0)return true;const template=state.templates[index];if(!confirm('Supprimer « '+template.name+' » de tes séances ? Ton historique, la séance en cours et les anciens plannings seront conservés.'))return true;creationSaving=true;state.templates.splice(index,1);try{await save();homeExpanded.delete(template.id);if(modelId===template.id)modelId=null;render();toast('Séance supprimée · historique conservé')}catch(error){state.templates.splice(index,0,template);render();toast('Suppression non enregistrée. Réessaie.')}finally{creationSaving=false}return true}if(k==='home-model'){view='models';modelId=state.templates[Number(v)].id;render();window.scrollTo(0,0);return true}if(k==='picker-close'){exercisePicker=null;render();return true}if(k==='picker-add'){const t=target(),e=clone(exercisePicker.choices[Number(v)]);e.instanceId=uid();e.sets=[];if(e.activityEntries)e.activityEntries=[];delete e.activityDraft;delete e.cardioTimer;delete e.superset;if(e.alternative){e.alternative.sets=[];e.alternative.instanceId=e.instanceId}if(exercisePicker.replace===null)t.exercises.push(e);else{const old=t.exercises[exercisePicker.replace];if(groupForExercise(t,old.instanceId))throw Error('Dissocie le groupe avant de remplacer cet exercice.');if(hasRecorded(old))throw Error('Conserve cet exercice : il contient des performances enregistrées.');t.exercises[exercisePicker.replace]=e}exercisePicker=null;await save();render();return true}if(k==='cancel-created'){creationDraft=null;state.templateDraft=null;await save();modelId=null;view='home';render();return true}if(k==='save-created'){const t=creationDraft;if(!t?.name.trim()||!t.exercises.length){$('#creation-error').textContent='Choisis au moins un exercice et donne un nom à la séance.';return true}creationSaving=true;const controls=[...document.querySelectorAll('main input,main select,main button,main textarea')].map(el=>[el,el.disabled,el.readOnly]);for(const [el] of controls){if(el.matches('button,select'))el.disabled=true;else el.readOnly=true}const button=$('[data-action="save-created"]');button.textContent='Enregistrement…';const saved=clone(t);saved.name=saved.name.trim();ensureInstances(saved);migrateGroups(saved);state.templates.push(saved);state.templateDraft=null;try{await save();creationDraft=null;modelId=null;view='home';render();toast('Séance enregistrée')}catch(error){state.templates=state.templates.filter(e=>e.id!==saved.id);state.templateDraft=creationDraft;$('#creation-error').textContent='Échec de sauvegarde. Ta séance reste prête à enregistrer.';button.disabled=false}finally{creationSaving=false;for(const [el,disabled,readOnly] of controls)if(el.isConnected){el.disabled=disabled;if('readOnly' in el)el.readOnly=readOnly}if(button.isConnected)button.textContent='Enregistrer la séance'}return true}return false}
function models(){const t=modelId==='new'?creationDraft:state.templates.find(t=>t.id===modelId);return `<div class="row between">${t?btn('←','model-editor-close','small editor-back'):''}<h1>${modelId==='new'&&!t?.exercises.length?'Créer une séance.':t?esc(t.name):'Mes séances.'}</h1>${!t?btn('Créer une séance','create-model','primary'):''}</div>${t?editor(t,false):state.templates.map(t=>`<div class="card row between"><h3>${esc(t.name)}</h3><div>${btn('Modifier','model:'+t.id,'small')}${btn('Dupliquer','clone-model:'+t.id,'small')}${btn('Supprimer','delete-model:'+encodeURIComponent(t.id),'small danger')}</div></div>`).join('')}`}
function editor(t,active,planning=false){if(!active&&!planning)return compactEditor(t,modelId==='new',state,{simplePrescription,lateralityControl,muscleTags,planControl,editorPreview});return `<div class="card"><h3>${modelId==='new'?'Contenu de la séance':planning?'Adapter le brouillon de séance':active?'Adapter uniquement cette séance':'Modifier le modèle'}</h3>${!active&&modelId!=='new'?`<label>Nom<input data-field="name" value="${esc(t.name)}"></label>`:''}${!active?`<label>Type de séance<select data-field="workoutType">${options([['','Personnalisée'],...workoutTypes],workoutType(t)||'')}</select></label>`:''}<p class="subtitle">${modelId==='new'?'Choisis tes exercices, puis enregistre ta séance.':planning?'Copie indépendante : aucune modification du modèle source.':active?'Ces objectifs concernent cette séance uniquement.':'Ces objectifs concernent les futures séances uniquement.'}${modelId==='new'?'':' Les séries enregistrées sont conservées.'}</p><div id="editor-preview">${editorPreview(t)}</div>${workoutOrder(t)}${modelGroups(t,active)}${t.exercises.map((e,i)=>`<section class="model-exercise">${modelPlanHeader(t,e,i,active)}${!active||isTimedExercise(e)?simplePrescription(e,i):''}${lateralityControl(e,i)}<details data-panel-key="model:${esc(e.instanceId)}"><summary>Réglages avancés · ${i+1}. ${esc(exerciseDisplayName(e))}</summary><label>Nom<input data-ex="${i}" data-field="name" value="${esc(exerciseDisplayName(e))}"></label><label>Matériel ou variante<select data-ex="${i}" data-field="variant-choice"><option value="keep">Conserver le même matériel</option><option value="new">Utiliser un autre matériel ou une autre variante</option></select></label><p class="subtitle">Un autre matériel garde ses propres performances.</p>${!active&&!(planning&&planner.remainingTarget()&&e.sets?.length)?muscleTags(e)+btn('Modifier les muscles','muscle-model:'+i,'small'):''}${planning?`<label>Matériel<select data-ex="${i}" data-field="equipment">${options([['unknown','À préciser'],...equipmentTypes],exerciseProfile(e,state.programmingPreferences).equipment)}</select></label><label>Mouvement<select data-ex="${i}" data-field="movement">${options(movementTypes,exerciseProfile(e,state.programmingPreferences).movement)}</select></label><label>Demande qualitative<select data-ex="${i}" data-field="demand">${options([['unknown','À préciser'],['low','Faible'],['moderate','Modérée'],['high','Exigeante']],exerciseProfile(e,state.programmingPreferences).demand)}</select></label><label>Répétitions · minimum<input data-ex="${i}" data-field="repMin" inputmode="numeric" value="${e.prescription?.repMin||prescription(e,state.programmingPreferences,state.sessions).repMin}"></label><label>Répétitions · maximum<input data-ex="${i}" data-field="repMax" inputmode="numeric" value="${e.prescription?.repMax||prescription(e,state.programmingPreferences,state.sessions).repMax}"></label><label>Repère d’effort (sans saisie obligatoire en séance)<input data-ex="${i}" data-field="effortHint" maxlength="500" value="${esc(e.prescription?.effort||'Garder des répétitions possibles')}"></label><label>Séries de préparation estimées<input data-ex="${i}" data-field="preparationSets" inputmode="numeric" value="${e.preparationSets??(exerciseProfile(e,state.programmingPreferences).demand==='high'?2:1)}"></label>`:''}${!isActivity(e)?`<label>Convention de charge<select data-ex="${i}" data-field="convention">${options(['Valeur indiquée (à préciser)','Total','Par haltère','Par côté','Affichage machine'].map(x=>[x,x]),e.convention)}</select></label><label>Incrément de charge (kg)<input data-ex="${i}" data-field="step" inputmode="decimal" value="${e.step}"></label>`:''}${active&&!isActivity(e)?`<label>Repos (secondes)<input data-ex="${i}" data-field="rest" inputmode="numeric" value="${e.rest}"></label>`:''}<div class="row">${btn('Remplacer','replace-ex:'+i,'small')}${btn('Retirer','remove-ex:'+i,'small danger')}</div></details></section>`).join('')}${btn('+ Ajouter un exercice','add-ex')}${modelId==='new'?`<label class="creation-name">Nom de la séance<input id="creation-name" data-field="name" maxlength="200" placeholder="Ex. Upper du vendredi" value="${esc(t.name)}"></label><p id="creation-error" role="alert"></p><div class="row">${btn('Enregistrer la séance','save-created','primary')}${btn('Annuler','cancel-created')}</div>`:btn('Fermer','close-editor','primary')}</div>`}
function profileObjectives(){return `${btn('← Profil','account-profile','small section-back')}<h1>Mes objectifs.</h1>${muscleDashboard()}`}
async function recommendApp(){const url=appRecommendationUrl(location.href);if(navigator.share)try{await navigator.share({title:'Élan',text:'Élan, pour suivre tes entraînements et progresser.',url});return}catch(error){if(error.name==='AbortError')return}try{await navigator.clipboard.writeText(url);toast('Lien de l’application copié.')}catch{const dialog=document.createElement('dialog');dialog.className='recommend-dialog';dialog.innerHTML=`<h2>Recommander Élan</h2><label>Lien de l’application<input readonly value="${esc(url)}"></label><form method="dialog"><button>Fermer</button></form>`;dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal();const field=dialog.querySelector('input');field.focus();field.select()}}
function settings(){return `${btn('← Profil','account-profile','small section-back')}<div class="eyebrow">TES DONNÉES T’APPARTIENNENT</div><h1>Réglages.</h1><div class="card"><h3>Sauvegarde et transfert</h3><p class="muted">Tes modifications sont enregistrées automatiquement. Garde une sauvegarde pour retrouver tes données si tu changes d’appareil ou effaces le stockage du navigateur.</p><div class="tools">${btn('Sauvegarder mes données','export','primary')}${btn('Restaurer une sauvegarde','import')}${btn('Exporter le tableau des séries','csv')}</div><input id="file" class="file" type="file" accept="application/json,.json"></div><div class="card"><h3>Sur ton iPhone</h3><p class="muted">Dans Safari : Partager → Sur l’écran d’accueil. Après un premier chargement, Élan reste accessible hors connexion.</p></div><div class="card"><h3>À propos des charges</h3><p class="muted">Les valeurs ne sont jamais doublées. Précise le matériel et la convention de charge de chaque exercice. Les variantes restent séparées pour comparer ce qui est comparable.</p></div>${social.advancedSettingsHtml()}` }
function download(name,text,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function target(){if(modelId==='new')return creationDraft;if(modelId==='planning')return planner.target();return modelId==='active'?state.active:state.templates.find(t=>t.id===modelId)}
function parseSet(prefix=''){const field=id=>$('#'+prefix+id);if(!field('weight').value.trim())throw Error('Renseigne la charge utilisée (0 kg si nécessaire).');if(!field('reps').value.trim())throw Error('Renseigne les répétitions.');const w=num(field('weight').value),r=num(field('reps').value),rir=field('rir').value.trim();if(!Number.isFinite(w)||w<0||!Number.isInteger(r)||r<1)throw Error('Indique une charge positive ou nulle et des répétitions entières supérieures à zéro.');if(rir!==''&&(!Number.isInteger(num(rir))||num(rir)<0))throw Error('RIR invalide.');const drops=field('drops').value.trim().split('\n').filter(Boolean).map(line=>{const parts=line.trim().split(/\s*[×xX;]\s*/);const w=num(parts[0]),r=num(parts[1]);if(parts.length!==2||!Number.isFinite(w)||w<0||!Number.isInteger(r)||r<1)throw Error('Dégressive : utilise « 25 × 8 », une étape par ligne.');return {w,r}});return {id:uid(),w,r,type:field('type').value,rir:rir===''?null:num(rir),notes:field('notes').value,drops}}
let timerEnd=state.active?.restUntil||0;
function restSelector(){const choice=restContext(state.active,ex(),currentGroup(),currentStage()),values=[...new Set([0,30,45,60,90,120,150,180,240,300,600,choice.seconds])].sort((a,b)=>a-b);return `<label class="next-rest">Repos<select id="next-rest">${options(values.map(n=>[n,restLabel(n)]),choice.seconds)}</select></label>`}
function restDialog(){return view==='work'&&state.active?.restOverlayOpen&&timerEnd>Date.now()?`<dialog id="rest-dialog" aria-labelledby="rest-title"><h2 id="rest-title" tabindex="-1" autofocus>Repos</h2><div id="rest-countdown" role="timer" aria-label="Temps de repos restant">${restLabel(Math.max(0,Math.ceil((timerEnd-Date.now())/1000)))}</div><p>Prochaine série · ${esc(ex()?.name)}</p><div class="rest-dialog-actions">${btn('Terminer le repos','rest-stop','primary wide')}${btn('Réduire','rest-dismiss','wide')}</div><div class="rest-feedback-slot"></div></dialog>`:''}
function syncRestDialog(){if(validationBusy)return;const cardio=$('#cardio-dialog');if(cardio&&!cardio.open){document.activeElement?.blur();cardio.showModal();$('#cardio-title').focus({preventScroll:true})}updateCardioClock();const dialog=$('#rest-dialog');if(dialog&&!dialog.open){document.activeElement?.blur();dialog.showModal();$('#rest-title').focus({preventScroll:true})}trainingFeedback.relocate();updateRestClock()}
function updateRestClock(){if(validationBusy||correctionSaving)return;const n=Math.max(0,Math.ceil((timerEnd-Date.now())/1000)),el=$('#timer');if(el)el.textContent=n?'Repos '+restLabel(n):timerEnd?'Repos terminé':'';if($('#rest-countdown'))$('#rest-countdown').textContent=restLabel(n);if(!n&&state.active?.restOverlayOpen&&!validationBusy&&!correctionSaving){state.active.restOverlayOpen=false;if($('#rest-dialog')){$('#rest-dialog').close();$('#rest-dialog').remove();trainingFeedback.relocate();focusEntry()}save().catch(()=>{})}}
