function sessionDetail({finished=false}={}){const s=state.sessions.find(x=>x.id===detail);if(!s)return history();const model=savedSessionModel(s,state.sessions,state.sessions.find(x=>x.id===comparisonId&&x.id!==s.id&&Date.parse(x.date)<=Date.parse(s.date))||null);return savedSessionHtml(model,state.sessions,{backAction:finished?'saved-home':'back-detail',backLabel:finished?'Accueil':detailOrigin==='history'?'Historique':detailOrigin==='progress'?'Progression':detailOrigin==='exercise-sheet'?'Exercice':'Bilan',groups:historyGroups(s).replaceAll('class="history-group"','class="saved-plan-group social-disclosure"').replaceAll('data-panel-key="history:', 'data-panel-key="saved-plan-history:'),progress:recapProgressSection(s,model.items),comparisonControls:comparisonControls(s),tonnageDetails:sessionTonnageDetails(s),unclassifiedControls:unclassifiedLinks(s,false),omitted:omittedExercises(s,state.sessions).length?`<details class="recap-omitted"><summary>Absents par rapport à la séance précédente</summary>${omittedExercises(s,state.sessions).map(e=>`<p>${esc(exerciseDisplayName(e))} · ${e.sets} séries le ${date(e.date)}</p>`).join('')}</details>`:''})+`<details class="session-edit saved-edit"><summary>Modifier ou supprimer la séance</summary>${sessionEditorDetails()}</details>`}
