function exerciseSheetView(){if(!exerciseSheet)return '';const muscleOptions=`<details class="sheet-muscle-settings"><summary>Muscles et réglages</summary>${muscleTags(exerciseSheet)}${btn('Modifier les associations','muscle-library:'+encodeURIComponent(exerciseSheet.id),'small')}</details>`;if(isActivity(exerciseSheet))return `${btn('← Retour','exercise-back','small')}<h1>${exerciseSheet.tracking==='cardio'?exercisePrimaryIcon(exerciseSheet):''}${esc(exerciseLabel(exerciseSheet.name))}</h1>${muscleOptions}${state.sessions.flatMap(s=>s.exercises.filter(e=>e.id===exerciseSheet.id).map(e=>`<article class="card"><h3>${date(s.date)}</h3>${(e.activityEntries||[]).map(x=>`<p>${fmt(activityDisplayValue(e,x))} ${activityDisplayUnit(e,x.counter)}</p>`).join('')||'Aucun relevé'}</article>`)).reverse().join('')||'<p>Aucun relevé enregistré.</p>'}`;const data=exerciseSheetData(exerciseSheet,state.sessions),weights=data.weights,activeWeight=exerciseWeight??weights.at(-1)??null;return `${btn('← Retour','exercise-back','small')}${muscleOptions}<div class="exercise-metric-tabs">${btn('Charge','exercise-metric:load',exerciseMetric==='load'?'selected':'')}${btn('Répétitions','exercise-metric:reps',exerciseMetric==='reps'?'selected':'')}</div>${exerciseMetric==='reps'?`<label>Charge fixe<select id="exercise-fixed-load">${options(weights.map(w=>[w,fmt(w)+' kg']),activeWeight)}</select></label>`:''}${sheetHtml({exercise:exerciseSheet,sessions:state.sessions,metric:exerciseMetric,weight:exerciseMetric==='reps'?activeWeight:null})}${identitySettings(exerciseSheet)}`}
