function identitySettings(exercise){return `<details class="identity-settings"><summary>Convention de charge</summary><p class="subtitle">Réglages hors entraînement. Aucune charge historique n’est multipliée ni réécrite.</p><label>Convention<select id="identity-convention">${options(['Charge totale','Par haltère','Par côté','Charge affichée machine','Charge additionnelle','Inconnue'].map(v=>[v,v]),loadIdentity(exercise).convention)}</select></label><label>Comptage des côtés<select id="identity-sides">${options(Object.entries(lateralModeLabels),loadIdentity(exercise).lateralMode)}</select></label>${btn('Appliquer aux futures séances','identity-future','small')}<details><summary>Confirmer des séries passées</summary><label>Du<input type="date" id="identity-from"></label><label>Au<input type="date" id="identity-to"></label><p class="subtitle">Uniquement cet exercice personnel, sur ces dates. Les valeurs saisies restent identiques. La confirmation est conservée et annulable.</p>${btn('Confirmer cette plage','identity-history','small')}${(state.conventionConfirmations||[]).filter(p=>p.exerciseId===exercise.id&&!p.undone).map(p=>btn('Annuler la confirmation du '+date(p.createdAt),'identity-undo:'+p.id,'small')).join('')}</details><p id="identity-message" role="status"></p></details>`}

async function evolutionAction(a){const [key,v,n]=a.split(':');if(key==='overview-tab'){overviewTab=v;performanceDetail=false;view='progress';progressTab='performance';render();return true}if(key==='overview-muscle'){overviewMuscle=v;overviewTab='muscle';render();return true}if(key==='performance-detail'){performanceDetail=true;view='progress';progressTab='performance';render();return true}if(key==='overview-tonnage'){view='progress';progressTab='performance';performanceDetail=false;overviewTab='tonnage';render();return true}if(key==='library-filter'){libraryMuscle=v;render();return true}if(key==='home-sessions'){view='home';render();return true}if(key==='home-muscle'){const templateId=decodeURIComponent(v);homeMuscleDetail=homeMuscleDetail?.templateId===templateId&&homeMuscleDetail.muscle===n?null:{templateId,muscle:n};render();return true}if(key==='back-detail'){if(detailOrigin==='exercise-sheet'){const previous=pageReturns.pop();if(previous){restorePage(previous);render();window.scrollTo(0,previous.scroll)}}else{view=detailOrigin;render();window.scrollTo(0,scrollPositions.get(view)||0)}return true}if(key==='summary-detail'){const menu=$('.saved-options');if(menu)menu.open=false;if(view!=='detail'){view='detail';detailOrigin='summary';render()}const panel=$('.session-edit');panel.open=true;panel.scrollIntoView({block:'start'});return true}if(key==='exercise-open'){const exercise=v==='active'?state.active?.exercises[Number(n)]:v==='detail'?state.sessions.find(s=>s.id===detail)?.exercises[Number(n)]:performanceExercise(decodeURIComponent(v))||muscleLibraryExercises().find(e=>e.id===decodeURIComponent(v));openExerciseSheet(exercise);return true}if(key==='exercise-back'){const previous=pageReturns.pop();if(previous){restorePage(previous);render();window.scrollTo(0,previous.scroll)}else{view='progress';render()}return true}if(key==='exercise-metric'){exerciseMetric=v;render();return true}if(key==='exercise-session'){pageReturns.push({view,detail,selected,scroll:window.scrollY,exerciseSheet,exerciseMetric,exerciseWeight,detailOrigin});detail=v;detailOrigin='exercise-sheet';view='detail';render();window.scrollTo(0,0);return true}if(key==='history-scope'){historyRange=v;calendarDay='';historyDayOnly=false;render();return true}if(key==='identity-future'||key==='identity-history'||key==='identity-undo'){await applyIdentity(a);return true}return false}
async function applyIdentity(action){const e=exerciseSheet;if(!e)return;const identity={version:1,unit:'kg',convention:$('#identity-convention').value,lateralMode:$('#identity-sides').value,source:'confirmed'},before=clone(state);try{if(action==='identity-future'){const update=item=>{if(item.id===e.id){item.loadIdentity=clone(identity);item.convention=identity.convention}if(item.alternative)update(item.alternative)};for(const template of state.templates)template.exercises.forEach(update);exerciseSheet={...e,loadIdentity:identity,convention:identity.convention}}else if(action==='identity-history'){const from=$('#identity-from').value,to=$('#identity-to').value;if(!validDay(from)||!validDay(to)||from>to)throw Error('Choisis une plage de dates valide.');const patches=[];for(let i=0;i<state.sessions.length;i++){const session=state.sessions[i];if(dayKey(session.date)<from||dayKey(session.date)>to)continue;for(const item of session.exercises.filter(x=>x.id===e.id)){const result=confirmHistoricalIdentity(state.sessions[i],item.instanceId,identity);state.sessions[i]=result.session;patches.push(result.patch)}}state.conventionConfirmations??=[];state.conventionConfirmations.push({id:uid(),exerciseId:e.id,createdAt:new Date().toISOString(),from,to,patches});}else{const confirmation=state.conventionConfirmations?.find(x=>x.id===action.split(':')[1]);if(!confirmation)throw Error('Confirmation introuvable.');for(const patch of confirmation.patches){const i=state.sessions.findIndex(s=>s.id===patch.sessionId);if(i>=0)state.sessions[i]=undoHistoricalIdentity(state.sessions[i],patch)}confirmation.undone=true;}await save();render();toast('Convention enregistrée · valeurs préservées')}catch(error){state=before;$('#identity-message').textContent=error.message}}

function planRevision(template){return JSON.stringify({exercises:template.exercises.map(e=>({id:e.id,convention:e.convention,identity:e.loadIdentity||null,sets:plannedSets(e),reps:e.prescription||e.refs?.map(r=>r.r),rest:e.rest})),groups:(template.groups||[]).map(g=>({mode:g.mode,members:g.members.map(key=>template.exercises.find(e=>e.instanceId===key)?.id),rest:g.rest,restAfter:g.restAfter,common:template.exercises.find(e=>e.instanceId===g.common)?.id}))})}
function comparisonControls(session){const candidates=state.sessions.filter(s=>s.id!==session.id&&s.date<=session.date).sort((a,b)=>Number(b.templateId===session.templateId)-Number(a.templateId===session.templateId)||b.date.localeCompare(a.date)),other=candidates.find(s=>s.id===comparisonId),same=other&&other.templateId===session.templateId&&session.planRevision&&other.planRevision===session.planRevision&&planRevision(other)===planRevision(session);return `<details class="session-comparison"><summary>Comparer la répartition</summary><label>Séance<select id="compare-session">${options([['','Sans comparaison'],...candidates.map(s=>[s.id,date(s.date)+' · '+s.name])],other?.id||'')}</select></label>${other?`<p class="subtitle">${same?'Même modèle et version de plan.':'Contenus potentiellement différents : pas de comparaison globale de performance. Axes et échelle partagés pour le volume attribué.'}</p>`:''}</details>`}

