function performanceExercise(id){const base=allExercises().find(e=>e.id===id);if(base&&loadIdentity(base).certainty==='known')return base;for(const session of [...state.sessions].sort((a,b)=>b.date.localeCompare(a.date)))for(const exercise of session.exercises.filter(e=>e.id===id)){const set=workSets(exercise).find(s=>loadIdentity(exercise,s).certainty==='known');if(set){const identity=loadIdentity(exercise,set);return {...exercise,convention:identity.convention,loadIdentity:{version:1,unit:identity.unit,convention:identity.convention,lateralMode:identity.lateralMode,source:'confirmed'}}}}return base;}

